use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/ring-queue-tree-query176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-10-ring-queue-tree-query176";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let read=|p:&str|serde_json::from_slice::<Value>(&fs::read(p).unwrap()).unwrap();let mut analysis=read(&format!("{R}/analysis.json"));let rows=analysis.as_object_mut().unwrap().remove("rows").unwrap();assert_eq!(rows.as_array().unwrap().len(),348);analysis["all_raw_rows_archive_member"]=json!("analysis.json");analysis["raw_analysis_sha256"]=json!(hash(&format!("{R}/analysis.json")));fs::write(format!("{D}/artifacts/analysis.json"),serde_json::to_vec_pretty(&analysis).unwrap()).unwrap();let raw=read(&format!("{R}/receipts.json"));let commands=raw.as_array().unwrap().iter().map(|v|{let folder=v["workflow"].as_str().unwrap();let name=v["name"].as_str().unwrap();json!({"workflow":folder,"name":name,"returncode":v["exit"]["returncode"],"command_json_sha256":hash(&format!("{R}/{folder}/{name}/command.json")),"exit_json_sha256":hash(&format!("{R}/{folder}/{name}/exit.json"))})}).collect::<Vec<_>>();assert_eq!(commands.len(),387);fs::write(format!("{D}/artifacts/receipts.json"),serde_json::to_vec_pretty(&json!({"commands":commands,"full_records_archive_member":"receipts.json","raw_receipts_sha256":hash(&format!("{R}/receipts.json"))})).unwrap()).unwrap();let meta=json!({"all_observations_retained":true,"archive_contains_full_raw_analysis_and_receipts":true,"public_analysis_omits_only_duplicate_per_job_rows":348,"public_receipts_replaced_only_by_command_exit_hash_index":387,"raw_analysis_sha256":hash(&format!("{R}/analysis.json")),"raw_receipts_sha256":hash(&format!("{R}/receipts.json")),"public_analysis_sha256":hash(&format!("{D}/artifacts/analysis.json")),"public_receipts_sha256":hash(&format!("{D}/artifacts/receipts.json")),"scientific_inputs_results_or_gates_changed":false});fs::write(format!("{D}/artifacts/public-views.json"),serde_json::to_vec_pretty(&meta).unwrap()).unwrap();fs::copy(format!("{R}/compact-publication.rs"),format!("{D}/artifacts/compact-publication.rs")).unwrap();let p=format!("{D}/README.md");let md=fs::read_to_string(&p).unwrap().replace("[full analysis](artifacts/analysis.json)","[analysis summary](artifacts/analysis.json)");fs::write(p,format!("{md}\nPer-job rows and full command records remain in the indexed archive. Public JSON omits only those duplicated payloads; [raw/public hashes](artifacts/public-views.json) and the [view builder](artifacts/compact-publication.rs) bind both representations. Statistics, gates and observations are unchanged.\n")).unwrap();let mut files=BTreeMap::new();files.insert("README.md".to_owned(),hash(&format!("{D}/README.md")));for e in fs::read_dir(format!("{D}/artifacts")).unwrap(){let e=e.unwrap();let name=format!("artifacts/{}",e.file_name().to_str().unwrap());files.insert(name,hash(e.path().to_str().unwrap()));}fs::write(format!("{D}/SHA256SUMS"),files.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();println!("compacted duplicated public payloads;all348rows/387fullrecords remain archived;{}checksums",files.len());}
